324	    /// Interprets attributes for EFFECTS/§E: effect codes
325	    /// Handles effect codes that may have been split by the colon-based attribute parser.
326	    /// E.g., §E{fs:r} gets parsed as _pos0="fs", _pos1="r" instead of _pos0="fs:r"
327	    /// Also handles comma-separated effects like §E{cw,fs:w} which becomes _pos0="cw,fs", _pos1="w"
328	    /// </summary>
329	    /// <param name="isEffectVariable">
330	    /// Resolves a reconstructed code against the enclosing declaration's in-scope
331	    /// <c>eff</c> binders. Consulted <b>before</b> <see cref="EffectCodes.TryParseCompact"/>,
332	    /// per design-doc §7.2(b), so <c>§E{e}</c> binds the variable rather than failing
333	    /// the taxonomy lookup. A name the predicate rejects keeps today's behaviour.
334	    /// </param>
335	    /// <param name="effectVariableSink">Receives each code the predicate accepted, in source order.</param>
336	    public static Dictionary<string, string> InterpretEffectsAttributes(
337	        AttributeCollection attrs,
338	        Action<string>? reportUnknownCode = null,
339	        Func<string, bool>? isEffectVariable = null,
340	        ICollection<string>? effectVariableSink = null)
341	    {
342	        var effects = new Dictionary<string, string>();
343	
344	        // Derive colon-bearing codes from the taxonomy. This keeps source parsing
345	        // aligned with entries such as mut:col without another hand-maintained list.
346	        var effectPrefixes = new HashSet<string>(
347	            EffectCodes.ColonPrefixes,
348	            StringComparer.OrdinalIgnoreCase);
349	        // First, reconstruct all effect codes from the split positional attributes
350	        var effectCodes = new List<string>();
351	
352	        for (int i = 0; ; i++)
353	        {
354	            var code = attrs[$"_pos{i}"];
355	            if (string.IsNullOrEmpty(code)) break;
356	
357	            // Check if this contains comma-separated effects (e.g., "cw,fs" from §E{cw,fs:w})
358	            if (code.Contains(','))
359	            {
360	                var parts = code.Split(',');
361	                // Add all but the last part as complete effect codes
362	                for (int j = 0; j < parts.Length - 1; j++)
363	                {
364	                    effectCodes.Add(parts[j]);
365	                }
366	                // The last part might be a prefix that needs combining with next positional
367	                var lastPart = parts[parts.Length - 1];
368	                if (effectPrefixes.Contains(lastPart.ToLowerInvariant()))
369	                {
370	                    var nextCode = attrs[$"_pos{i + 1}"];
371	                    if (!string.IsNullOrEmpty(nextCode))
372	                    {
373	                        // Check if nextCode is a modifier or contains comma-separated values
374	                        var nextParts = nextCode.Split(',');
375	                        if (!string.IsNullOrWhiteSpace(nextParts[0]))
376	                        {
377	                            // Combine: "fs" + "w" -> "fs:w"
378	                            effectCodes.Add($"{lastPart}:{nextParts[0]}");
379	                            i++; // Skip the next positional since we consumed it
380	
381	                            // If there were more parts after the modifier, check if
382	                            // any are prefixes needing their own modifier from further positionals
383	                            for (int k = 1; k < nextParts.Length; k++)
384	                            {
385	                                var remainingPart = nextParts[k];
386	                                if (effectPrefixes.Contains(remainingPart.ToLowerInvariant()))
387	                                {
388	                                    // This remaining part is a prefix — look for its modifier
389	                                    var futureCode = attrs[$"_pos{i + 1}"];
390	                                    if (!string.IsNullOrEmpty(futureCode))
391	                                    {
392	                                        var futureParts = futureCode.Split(',');
393	                                        if (!string.IsNullOrWhiteSpace(futureParts[0]))
394	                                        {
